parameters.jsCode:
const agora = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/Sao_Paulo' }));
const mensagem = $input.first().json.mensagem_concatenada || '';
const remoteJid = $input.first().json.remoteJid;

const diasSemana = {
  'domingo': 0, 'dom': 0,
  'segunda-feira': 1, 'segunda': 1,
  'terca-feira': 2, 'terca': 2,
  'quarta-feira': 3, 'quarta': 3,
  'quinta-feira': 4, 'quinta': 4,
  'sexta-feira': 5, 'sexta': 5,
  'sabado': 6
};

const nomesExibicao = ['domingo','segunda-feira','terça-feira','quarta-feira','quinta-feira','sexta-feira','sábado'];
const meses = ['janeiro','fevereiro','março','abril','maio','junho','julho','agosto','setembro','outubro','novembro','dezembro'];

const msgLower = mensagem.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');

function addDays(date, days) {
  const result = new Date(date);
  result.setDate(result.getDate() + days);
  return result;
}

let dataResolvida = null;

if (msgLower.includes('hoje')) {
  dataResolvida = agora;
} else if (msgLower.includes('depois de amanha')) {
  dataResolvida = addDays(agora, 2);
} else if (msgLower.includes('amanha')) {
  dataResolvida = addDays(agora, 1);
} else {
  const hojeSemana = agora.getDay();
  const entradasOrdenadas = Object.entries(diasSemana).sort((a, b) => b[0].length - a[0].length);
  for (const [nome, diaSemana] of entradasOrdenadas) {
    if (msgLower.includes(nome)) {
      let diff = diaSemana - hojeSemana;
      if (diff <= 0) diff += 7;
      dataResolvida = addDays(agora, diff);
      break;
    }
  }
}

let dataFormatada = null;
let dataExibicao = null;
let dataNovaEncontrada = false;

if (dataResolvida) {
  const yyyy = dataResolvida.getFullYear();
  const mm = String(dataResolvida.getMonth() + 1).padStart(2, '0');
  const dd = String(dataResolvida.getDate()).padStart(2, '0');
  dataFormatada = `${yyyy}-${mm}-${dd}`;
  const nomeDia = nomesExibicao[dataResolvida.getDay()];
  const nomeMes = meses[dataResolvida.getMonth()];
  dataExibicao = `${nomeDia}, ${dd} de ${nomeMes} de ${yyyy}`;
  dataNovaEncontrada = true;
}

return {
  mensagem_concatenada: $input.first().json.mensagem_concatenada,
  remoteJid: remoteJid,
  email_cliente: $input.first().json.email_cliente,
  data_interpretada: dataFormatada,
  data_exibicao: dataExibicao,
  data_nova_encontrada: dataNovaEncontrada
};
